script:
test("weekend gap does not break an absence streak", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});

test("a present day resets the count to 0", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});

test("a longer streak returns the date it reached 3, not a later absence", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});

test("only the first date any streak reached 3 is returned", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "present" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" },
    { date: "2024-01-12", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});

test("empty input never reaches 3", function () {
  assert.equal(code.firstThreeDayAbsenceStreak([]), null);
});

test("no run of 3 consecutive absences returns nothing", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});

test("after a present day resets the count, the first later streak of 3 returns that third date", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-11");
});

test("three consecutive absent school days return the third date", function () {
  var days = [
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-10");
});
